// Single-policy portfolio controls. Replays use the unmodified saved evaluation;
// no results are generated by this tour. See ../../../NOTICE.txt.
const byId = id => document.getElementById(id);
const driveButton = byId('showcase-drive');
const tourButton = byId('showcase-tour');
const status = byId('showcase-tour-status');
const progress = byId('showcase-tour-progress');
const root = document.querySelector('.demo');
const tourRounds = [
  ['track-forward-1:r1', 'Track a forward command'],
  ['track-left-0.5:r1', 'Step sideways'],
  ['track-cw-1:r1', 'Turn on command'],
  ['brake-forward-1:r1', 'Brake and hold still'],
  ['capacity-forward-3:r1', 'Find the tested limit'],
];
let activeTour = 0;
let originalResult;

async function ensureReady() {
  const debug = window.k1gallery;
  if (!debug) throw Error('The policy viewer did not initialize. Please reload.');
  await debug.evaluation.ready;
  if (debug.started) return debug;
  await new Promise((resolve, reject) => {
    const cleanup = () => {
      clearTimeout(timeout);
      window.removeEventListener('pal-policy-ready', loaded);
      window.removeEventListener('pal-policy-error', failed);
    };
    const loaded = () => { cleanup(); resolve(); };
    const failed = event => { cleanup(); reject(Error(event.detail || 'Policy loading failed.')); };
    const timeout = setTimeout(() => { cleanup(); reject(Error('Loading took too long. Check your connection and try again.')); }, 90000);
    window.addEventListener('pal-policy-ready', loaded);
    window.addEventListener('pal-policy-error', failed);
    const load = document.querySelector('.demo-start-button');
    if (!load.disabled) load.click();
  });
  return debug;
}

function finishTour(evaluation, message = '') {
  activeTour++;
  tourButton.dataset.running = 'false';
  if (originalResult) evaluation.showResult(originalResult);
  evaluation.exitReplay();
  tourButton.textContent = 'Replay evaluation';
  progress.hidden = true;
  status.textContent = message;
}

driveButton.addEventListener('click', async () => {
  driveButton.disabled = true;
  status.textContent = 'Loading the trained policy…';
  try {
    const { evaluation } = await ensureReady();
    if (evaluation.isRunning) { status.textContent = 'End the current evaluation to take the controls.'; return; }
    finishTour(evaluation, 'Live policy · use W/S to walk, A/D to sidestep, Q/E to turn, or drag the joystick.');
    root.focus({ preventScroll: true });
  } catch (error) { status.textContent = error.message; }
  finally { driveButton.disabled = false; }
});

tourButton.addEventListener('click', async () => {
  const debug = window.k1gallery;
  if (tourButton.dataset.running === 'true') {
    tourButton.dataset.running = 'false';
    finishTour(debug.evaluation, 'Replay stopped. The full saved scorecard is shown below.');
    return;
  }
  tourButton.disabled = true;
  status.textContent = 'Loading saved evaluation and recorded robot poses…';
  try {
    const { evaluation } = await ensureReady();
    if (evaluation.isRunning) { status.textContent = 'End the current evaluation before starting a replay.'; return; }
    // A visitor may have run a newer local evaluation. The tour always uses the
    // shipped October 6 snapshot advertised by this page.
    if (!originalResult) {
      originalResult = evaluation.result?.completedAt === '2026-10-06T16:41:14.150Z'
        ? evaluation.result
        : await fetch('../saved-evaluations/walk-flat-amp/k1_amp_legs_ref_turn.json').then(response => {
          if (!response.ok) throw Error('The saved evaluation could not be loaded.');
          return response.json();
        });
    }
    if (!originalResult?.attempts?.length) throw Error('The saved scorecard is unavailable. You can still drive the policy or run a quick check.');
    evaluation.result = originalResult;
    evaluation.showResult(originalResult);
    const tourId = ++activeTour;
    tourButton.dataset.running = 'true';
    tourButton.textContent = 'Stop replay';
    tourButton.disabled = false;
    progress.hidden = false;
    progress.value = 0;
    evaluation.gem.setPoints([]);
    byId('result-state').textContent = 'Recorded map replay';
    for (const [index, [id, label]] of tourRounds.entries()) {
      if (activeTour !== tourId) break;
      const attempt = originalResult.attempts.find(item => item.id === id);
      if (!attempt) continue;
      evaluation.selectAttempt(attempt);
      evaluation.playReplay = true;
      const resultLabel = attempt.passed ? 'passed' : 'did not pass';
      status.textContent = `Recorded evaluation · ${index + 1}/${tourRounds.length} · ${label} · ${resultLabel}`;
      await new Promise(resolve => {
        const tick = () => {
          if (activeTour !== tourId || !evaluation.playReplay || evaluation.isRunning || !evaluation.replaying) { resolve(); return; }
          progress.value = (index + evaluation.replayIndex / Math.max(1, evaluation.replayTrace.length - 1)) / tourRounds.length;
          requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      });
      if (activeTour !== tourId) break;
      // Progressively reveal genuine saved samples; never invent measured points.
      evaluation.gem.setPoints(originalResult.envelope.filter(point => {
        const [forward, left, turn] = point.command;
        return (forward > 0 && Math.abs(left) < .01 && Math.abs(turn) < .01)
          || (index >= 1 && left > 0)
          || (index >= 2 && Math.abs(turn) > 0);
      }));
    }
    if (activeTour === tourId) finishTour(evaluation, 'Replay complete · full saved evaluation: 162 of 228 attempts passed. The motion gem shows measured passes; four falls occurred across the full test circuit.');
  } catch (error) { status.textContent = error.message; }
  finally {
    tourButton.disabled = false;
    if (tourButton.textContent !== 'Stop replay') tourButton.dataset.running = 'false';
  }
});

// Real input events use the same policy command path as the keyboard.
document.querySelectorAll('[data-command-key]').forEach(button => {
  const key = button.dataset.commandKey;
  let held = false;
  const release = () => {
    if (!held) return;
    held = false;
    root.dispatchEvent(new KeyboardEvent('keyup', { code: key, bubbles: true }));
    button.classList.remove('is-held');
  };
  button.addEventListener('pointerdown', event => {
    if (!window.k1gallery?.started) return;
    event.preventDefault();
    root.focus({ preventScroll: true });
    held = true;
    button.setPointerCapture(event.pointerId);
    root.dispatchEvent(new KeyboardEvent('keydown', { code: key, bubbles: true }));
    button.classList.add('is-held');
  });
  button.addEventListener('pointerup', release);
  button.addEventListener('pointercancel', release);
  button.addEventListener('lostpointercapture', release);
  window.addEventListener('blur', release);
});

// End the guided tour whenever a visitor chooses a different mode or round.
for (const selector of ['#run-gauntlet', '#run-smoke', '#replay-exit', '.demo-reset', '#round-list', '#motion-gem']) {
  document.querySelector(selector)?.addEventListener('click', () => {
    if (tourButton.dataset.running !== 'true') return;
    activeTour++;
    tourButton.dataset.running = 'false';
    tourButton.textContent = 'Replay evaluation';
    progress.hidden = true;
    if (originalResult) window.k1gallery.evaluation.gem.setPoints(originalResult.envelope);
    status.textContent = '';
  });
}
